    except Exception as e:
        print(f"错误: {e}")
        if args.verbose:
            print(traceback.format_exc())
        sys.exit(1)
    finally:
        # 清理资源
        if runner and runner.clients:
            try:
                asyncio.run(runner.cleanup())
