// Neo4j端API处理
function handleCreateRelationship(req, res) {
  const session = driver.session();
  const { sourceId, targetId, relationType, properties } = req.body;

  // 验证关系类型的约束条件
  session.run(`
    MATCH (rt:RelationType {name: $relationType})
    RETURN rt.allowed_properties as allowed, 
           rt.source_types as sourcetypes, 
           rt.target_types as targettypes
  `, { relationType })
  .then(result => {
    const record = result.records[0];
    if (!record) {
      throw new Error("未定义的关系类型");
    }

    // 验证属性
    const allowedProps = record.get('allowed');
    const validProps = {};
    for (const key in properties) {
      if (allowedProps.includes(key)) {
        validProps[key] = properties[key];
      }
    }

    // 创建关系
    return session.run(`
      MATCH (source) WHERE ID(source) = $sourceId
      MATCH (target) WHERE ID(target) = $targetId
      CREATE (source)-[r:${relationType} $props]->(target)
      RETURN r
    `, { sourceId, targetId, props: validProps });
  })
  .then(result => {
    res.json({ success: true, relation: result.records[0].get('r') });
  })
  .catch(error => {
    res.status(400).json({ error: error.message });
  })
  .finally(() => session.close());
}
```

