// 自动发现内容关系
async function discoverRelationships(newContentId) {
  // 1. 获取内容向量嵌入
  const contentEmbedding = await getContentEmbedding(newContentId);

  // 2. 查找相似内容
  const similarContent = await findSimilarContent(contentEmbedding, 0.75, 5);

  // 3. 创建相似度关系
  similarContent.forEach(similar => {
    createGraphRelationship(
      newContentId, 
      similar.id, 
      "SIMILAR_TO", 
      { score: similar.similarity }
    );
  });

  // 4. 分析引用和关键词匹配
  const references = extractReferences(newContentId);
  references.forEach(ref => {
    createGraphRelationship(
      newContentId, 
      ref.targetId, 
      "REFERENCES", 
      { context: ref.context }
    );
  });
}
