```javascript
// 将知识图谱导出为脑图格式
async function exportToMindMap(conceptId) {
  // 获取节点数据
  const rootNode = await getGraphNode(conceptId);

  // 获取所有子节点和关系
  const childRelations = await getNodeRelationships(conceptId, 'CONTAINS', 'outgoing');

  // 递归构建脑图结构
  function buildMindMapNode(node, relations) {
    const mindNode = {
      id: node.id,
      topic: node.title,
      expanded: true
    };

    // 添加子节点
    const childIds = relations
      .filter(rel => rel.source === node.id)
      .map(rel => rel.target);

    if (childIds.length > 0) {
      mindNode.children = [];

      for (const childId of childIds) {
        const childNode = nodeMap.get(childId);
        const childMindNode = buildMindMapNode(childNode, relations);
        mindNode.children.push(childMindNode);
      }
    }

    return mindNode;
  }

  // 构建完整脑图
  const mindMapData = {
    meta: {
      name: `Export-${rootNode.title}`,
      author: "Knowledge System Export",
      version: "1.0"
    },
    format: "node_array",
    data: buildMindMapNode(rootNode, childRelations)
  };

  return JSON.stringify(mindMapData, null, 2);
}
