## 一、脑图数据注入功能

### 1. 数据流程

```
脑图JSON文件 → 解析器 → 数据转换 → 存储系统 → 知识图谱
```

### 2. 关键组件

#### 2.1 脑图数据采集器

```javascript
// 脑图数据采集器
class MindMapCollector {
  constructor(apiService) {
    this.apiService = apiService;
  }

  // 读取脑图文件
  async readMindMapFile(filePath) {
    try {
      const content = await fs.promises.readFile(filePath, 'utf-8');
      return JSON.parse(content);
    } catch (error) {
      console.error(`读取脑图文件失败: ${error.message}`);
      throw error;
    }
  }

  // 处理脑图数据
  async processMindMap(mindMapData, options = {}) {
    const { generateRelationships = true, embeddingModel = 'default' } = options;

    // 记录脑图元数据
    const metadata = {
      source: 'mindmap',
      format: mindMapData.format || 'jsmind',
      timestamp: new Date().toISOString(),
      version: mindMapData.meta?.version || '1.0'
    };

    // 注册脑图源
    const sourceId = await this.apiService.registerDataSource({
      type: 'mindmap',
      name: mindMapData.meta?.name || '未命名脑图',
      metadata
    });

    // 处理节点
    const rootNode = mindMapData.data;
    await this.processNode(rootNode,, sourceId, generateRelationships, embeddingModel);

    return {
      sourceId,
      nodeCount: this.nodeCount,
      relationshipCount: this.relationshipCount
    };
  }

  // 递归处理节点
  async processNode(node, parentId, sourceId, generateRelationships, embeddingModel) {
    // 创建节点记录
    const nodeData = {
      id: node.id,
      title: node.topic || node.text || '',
      content_type: 'mindmap_node',
      source_id: sourceId,
      parent_id: parentId,
      metadata: {
        position: node.direction || node.position,
        expanded: node.expanded !== false,
        style: node.style || {},
        custom_data: node.data || {}
      }
    };

    // 保存到API服务
    const savedNode = await this.apiService.createNode(nodeData);
    this.nodeCount++;

    // 创建父子关系
    if (parentId) {
      await this.apiService.createRelationship({
        source_id: parentId,
        target_id: node.id,
        type: 'CONTAINS',
        metadata: { source: 'mindmap_structure' }
      });
      this.relationshipCount++;
    }

    // 生成向量嵌入
    if (node.topic || node.text) {
      await this.apiService.generateEmbedding(node.id, embeddingModel);
    }

    // 处理子节点
    if (node.children && node.children.length > 0) {
      for (const child of node.children) {
        await this.processNode(child, node.id, sourceId, generateRelationships, embeddingModel);
      }
    }

    // 发现潜在关系
    if (generateRelationships) {
      await this.apiService.discoverRelationships(node.id);
    }
  }
}
```

#### 2.2 API服务接口

```javascript
// 中间层API服务
class KnowledgeAPIService {
  constructor(config) {
    this.dbService = new DatabaseService(config.database);
    this.graphService = new GraphService(config.neo4j);
    this.vectorService = new VectorService(config.vector);
  }

  // 注册数据源
  async registerDataSource(sourceInfo) {
    const sourceId = uuidv4();
    await this.dbService.insertDataSource({
      id: sourceId,
      ...sourceInfo,
      created_at: new Date()
    });
    return sourceId;
  }

  // 创建节点
  async createNode(nodeData) {
    // 存储到PostgreSQL
    const savedNode = await this.dbService.insertNode(nodeData);

    // 创建图谱节点
    await this.graphService.createNode({
      id: nodeData.id,
      labels: ['Content', 'MindMapNode'],
      properties: {
        title: nodeData.title,
        content_type: nodeData.content_type,
        source_id: nodeData.source_id
      }
    });

    return savedNode;
  }

  // 创建关系
  async createRelationship(relationshipData) {
    // 存储关系元数据
    const relationshipId = uuidv4();
    await this.dbService.insertRelationship({
      id: relationshipId,
      ...relationshipData,
      created_at: new Date()
    });

    // 创建图谱关系
    await this.graphService.createRelationship({
      source_id: relationshipData.source_id,
      target_id: relationshipData.target_id,
      type: relationshipData.type,
      properties: relationshipData.metadata || {}
    });

    return relationshipId;
  }

  // 生成向量嵌入
  async generateEmbedding(nodeId, modelName = 'default') {
    // 获取节点内容
    const node = await this.dbService.getNodeById(nodeId);
    if (!node) throw new Error(`节点不存在: ${nodeId}`);

    // 生成文本向量
    const text = node.title + ' ' + (node.content || '');
    const embedding = await this.vectorService.generateEmbedding(text, modelName);

    // 保存向量
    await this.dbService.updateNodeEmbedding(nodeId, embedding);
    await this.vectorService.indexDocument({
      id: nodeId,
      embedding: embedding,
      metadata: {
        title: node.title,
        content_type: node.content_type
      }
    });

    return embedding;
  }

  // 发现关系
  async discoverRelationships(nodeId, options = {}) {
    const { similarityThreshold = 0.75, maxRelationships = 5 } = options;

    // 获取节点向量
    const node = await this.dbService.getNodeWithEmbedding(nodeId);
    if (!node || !node.embedding) {
      console.log(`节点 ${nodeId} 没有向量嵌入，跳过关系发现`);
      return [];
    }

    // 查找相似节点
    const similarNodes = await this.vectorService.findSimilar({
      embedding: node.embedding,
      threshold: similarityThreshold,
      limit: maxRelationships,
      exclude: [nodeId]
    });

    // 创建相似关系
    const relationships = [];
    for (const similar of similarNodes) {
      const relationshipData = {
        source_id: nodeId,
        target_id: similar.id,
        type: 'SIMILAR_TO',
        metadata: {
          similarity: similar.score,
          discovered: true,
          created_at: new Date()
        }
      };

      const relationshipId = await this.createRelationship(relationshipData);
      relationships.push({
        id: relationshipId,
        ...relationshipData
      });
    }

    return relationships;
  }
}
```

## 二、关系可视化增强功能

### 1. 数据流程

```
用户指定目标节点 → 关系查询 → 关系转换 → 脑图更新 → 脑图渲染
```

### 2. 关键组件

#### 2.1 关系扩展器

```javascript
// 脑图关系扩展器
class MindMapRelationshipExpander {
  constructor(apiService) {
    this.apiService = apiService;
  }

  // 获取节点的相关关系
  async getNodeRelationships(nodeId, options = {}) {
    const {
      relationshipTypes = ['SIMILAR_TO', 'REFERENCES', 'RELATES_TO'],
      maxDepth = 1,
      maxNodes = 20,
      includeProperties = true
    } = options;

    // 查询关系数据
    const relationships = await this.apiService.getNodeRelationships(
      nodeId,
      relationshipTypes,
      maxDepth,
      maxNodes
    );

    // 获取相关节点信息
    const nodeIds = new Set();
    nodeIds.add(nodeId); // 添加中心节点

    // 收集所有关联节点ID
    relationships.forEach(rel => {
      nodeIds.add(rel.source_id);
      nodeIds.add(rel.target_id);
    });

    // 获取节点详情
    const nodes = await this.apiService.getNodesByIds(Array.from(nodeIds));

    return {
      centralNodeId: nodeId,
      nodes,
      relationships
    };
  }

  // 将关系转换为脑图格式
  convertRelationshipsToMindMap(relationshipData, options = {}) {
    const {
      centralNodeId,
      nodes,
      relationships
    } = relationshipData;

    const {
      positionMapping = {
        'SIMILAR_TO': 'right',
        'REFERENCES': 'left',
        'RELATES_TO': 'bottom',
        'DERIVED_FROM': 'top',
        'CONTRADICTS': 'bottom-right'
      },
      colorMapping = {
        'SIMILAR_TO': '#36a3eb',
        'REFERENCES': '#4ecb73',
        'RELATES_TO': '#dfa53a',
        'DERIVED_FROM': '#8c5ad6',
        'CONTRADICTS': '#eb5252'
      }
    } = options;

    // 查找中心节点
    const centralNode = nodes.find(n => n.id === centralNodeId);
    if (!centralNode) {
      throw new Error(`未找到中心节点: ${centralNodeId}`);
    }

    // 构建脑图根节点
    const rootNode = {
      id: centralNode.id,
      topic: centralNode.title,
      direction: 'center',
      expanded: true,
      children: []
    };

    // 添加自定义样式
    if (centralNode.metadata && centralNode.metadata.style) {
      rootNode.style = centralNode.metadata.style;
    } else {
      rootNode.style = {
        'background-color': '#3498db',
        'color': '#ffffff'
      };
    }

    // 按关系类型分组
    const relationshipsByType = {};
    relationships.forEach(rel => {
      if (!relationshipsByType[rel.type]) {
        relationshipsByType[rel.type] = [];
      }
      relationshipsByType[rel.type].push(rel);
    });

    // 为每种关系类型创建分组节点
    Object.entries(relationshipsByType).forEach(([type, rels]) => {
      // 确定方向
      const direction = positionMapping[type] || 'right';

      // 创建关系类型分组节点
      const typeNode = {
        id: `group_${centralNodeId}_${type}`,
        topic: formatRelationType(type),
        direction: direction,
        children: [],
        expanded: true,
        style: {
          'background-color': colorMapping[type] || '#7e7e7e',
          'color': '#ffffff'
        }
      };

      // 添加关系节点
      rels.forEach(rel => {
        // 确定目标节点（非中心节点的那个）
        const targetId = rel.source_id === centralNodeId ? rel.target_id : rel.source_id;
        const targetNode = nodes.find(n => n.id === targetId);

        if (targetNode) {
          const childNode = {
            id: targetNode.id,
            topic: targetNode.title,
            direction: direction,
            data: {
              original_type: targetNode.content_type,
              relationship_type: type,
              relationship_id: rel.id,
              similarity: rel.metadata?.similarity
            }
          };

          // 添加关系属性信息
          if (rel.metadata && Object.keys(rel.metadata).length > 0) {
            // 将关系属性格式化为工具提示
            const tooltipContent = Object.entries(rel.metadata)
              .filter(([k, v]) => k !== 'style' && k !== 'created_at')
              .map(([k, v]) => `${formatPropertyName(k)}: ${formatPropertyValue(v)}`)
              .join('\n');

            childNode.data.tooltip = tooltipContent;
          }

          typeNode.children.push(childNode);
        }
      });

      // 只有当有子节点时才添加分组节点
      if (typeNode.children.length > 0) {
        rootNode.children.push(typeNode);
      }
    });

    // 构建完整脑图结构
    const mindMapData = {
      meta: {
        name: `关系视图: ${centralNode.title}`,
        author: "Knowledge System",
        version: "1.0"
      },
      format: "node_tree",
      data: rootNode
    };

    return mindMapData;
  }

  // 辅助函数：格式化关系类型名称
  formatRelationType(type) {
    const mapping = {
      'SIMILAR_TO': '相似概念',
      'REFERENCES': '引用关系',
      'RELATES_TO': '相关内容',
      'CONTAINS': '包含关系',
      'DERIVED_FROM': '衍生自',
      'CONTRADICTS': '存在矛盾'
    };

    return mapping[type] || type;
  }
}
```

#### 2.2 脑图更新器

