// 脑图更新服务
class MindMapUpdater {
  constructor(apiService) {
    this.apiService = apiService;
    this.expander = new MindMapRelationshipExpander(apiService);
  }

  // 创建关系视图
  async createRelationshipView(nodeId, options = {}) {
    // 获取节点关系
    const relationshipData = await this.expander.getNodeRelationships(nodeId, options);

    // 转换为脑图格式
    const mindMapData = this.expander.convertRelationshipsToMindMap(
      relationshipData,
      options
    );

    return mindMapData;
  }

  // 合并到现有脑图
  async mergeIntoExistingMindMap(existingMindMap, relationshipView, options = {}) {
    const {
      mergeBehavior = 'add_missing',  // 'add_missing', 'replace_all', 'smart_merge'
      preservePositions = true,
      preserveStyles = true
    } = options;

    // 获取现有节点映射
    const existingNodesMap = this.buildNodeMap(existingMindMap.data);

    // 合并策略
    if (mergeBehavior === 'replace_all') {
      // 完全替换中心节点的所有子节点
      const centralNodeId = relationshipView.data.id;
      if (existingNodesMap.has(centralNodeId)) {
        const existingNode = existingNodesMap.get(centralNodeId);
        existingNode.children = relationshipView.data.children;

        // 保留原始位置和样式
        if (preservePositions && existingNode.direction) {
          relationshipView.data.direction = existingNode.direction;
        }

        if (preserveStyles && existingNode.style) {
          relationshipView.data.style = existingNode.style;
        }
      }
    }
    else if (mergeBehavior === 'smart_merge') {
      // 智能合并 - 保留现有分组，添加新关系
      this.smartMergeNodes(existingMindMap.data, relationshipView.data, existingNodesMap);
    }
    else { // add_missing
      // 只添加缺失的节点
      this.addMissingNodes(existingMindMap.data, relationshipView.data, existingNodesMap);
    }

    return existingMindMap;
  }

  // 导出为JSMind格式文件
  async exportToJsMindFile(mindMapData, filePath) {
    try {
      await fs.promises.writeFile(
        filePath,
        JSON.stringify(mindMapData, null, 2),
        'utf-8'
      );
      return { success: true, path: filePath };
    } catch (error) {
      console.error(`导出脑图文件失败: ${error.message}`);
      throw error;
    }
  }

  // 构建节点映射
  buildNodeMap(rootNode) {
    const nodeMap = new Map();

    // 递归处理节点
    function processNode(node) {
      nodeMap.set(node.id, node);

      if (node.children && node.children.length > 0) {
        node.children.forEach(processNode);
      }
    }

    processNode(rootNode);
    return nodeMap;
  }

  // 智能合并节点
  smartMergeNodes(targetRoot, sourceRoot, existingNodesMap) {
    // 实现智能合并逻辑
    // ...
  }

  // 添加缺失节点
  addMissingNodes(targetRoot, sourceRoot, existingNodesMap) {
    // 实现添加缺失节点的逻辑
    // ...
  }
}
