```javascript
// 数据同步管理器
class DataSyncManager {
  constructor(apiService) {
    this.apiService = apiService;
    this.changeQueue = [];
    this.syncInterval = 2000; // 2秒同步一次
    this.isSyncing = false;

    setInterval(this.processSyncQueue.bind(this), this.syncInterval);
  }

  queueChange(changeType, entityType, entityId, data) {
    // 添加到变更队列
    this.changeQueue.push({
      id: uuidv4(),
      timestamp: Date.now(),
      changeType, // 'create', 'update', 'delete'
      entityType, // 'node', 'relationship'
      entityId,
      data
    });

    // 如果变更很重要，立即同步
    if (this.isHighPriorityChange(changeType, entityType)) {
      this.processSyncQueue(true);
    }
  }

  async processSyncQueue(immediate = false) {
    if (this.isSyncing || (this.changeQueue.length === 0)) return;

    this.isSyncing = true;

    try {
      // 按类型分组变更
      const changes = this.groupChangesByEntity();

      // 处理节点变更
      if (changes.nodes.length > 0) {
        await this.apiService.bulkUpdateNodes(changes.nodes);
      }

      // 处理关系变更
      if (changes.relationships.length > 0) {
        await this.apiService.bulkUpdateRelationships(changes.relationships);
      }

      // 清空已处理的变更
      this.changeQueue = [];
    } catch (error) {
      console.error('同步失败:', error);
      // 可以实现重试逻辑
    } finally {
      this.isSyncing = false;
    }
  }

  // 辅助方法...
}
```

